/**
 * Views, menus and task definitions contributed in package.json (generated by `npm run gen`).
 * Pure: no `vscode` import.
 */

export const VIEW_CONTAINERS = {
  // First in the activity bar: IntelliJ's Project tool window. VS Code's Explorer cannot host it
  // instead of its Folders view (that view cannot be hidden).
  activitybar: [
    { id: 'unintellij-project', title: 'Project', icon: 'media/project.svg' },
    // IntelliJ's Git tool window (log); left rather than at the bottom so that it is easy to find.
    { id: 'unintellij-git', title: 'Git', icon: 'media/git.svg' },
    // Left, under Commit; IntelliJ shows it on the right: drag it to the secondary side bar if wanted.
    { id: 'unintellij-database', title: 'Database', icon: 'media/database.svg' },
    // IntelliJ shows it on the right: drag it to the secondary side bar if wanted.
    { id: 'unintellij-maven', title: 'Maven', icon: 'media/maven.svg' },
  ],
  panel: [
    { id: 'unintellij-services', title: 'Services', icon: 'media/database.svg' },
  ],
};

export const VIEWS = {
  'unintellij-project': [{ id: 'unintellij.project', name: 'Project' }],
  'unintellij-database': [{ id: 'unintellij.database', name: 'Database' }],
  'unintellij-maven': [{ id: 'unintellij.maven', name: 'Maven', when: 'unintellij.mavenProjects' }],
  'unintellij-services': [{ type: 'webview', id: 'unintellij.dbResults', name: 'Database' }],
  'unintellij-git': [{ type: 'webview', id: 'unintellij.gitLog', name: 'Log' }],
  // In VS Code's Source Control container, whose native views UnIntelliJ hides (see scmViews.ts).
  // Expanded by default: contributed views are otherwise added collapsed at the bottom.
  scm: [{ type: 'webview', id: 'unintellij.commit', name: 'Commit', visibility: 'visible' }],
};

/** Activity bar container command for a container id, used by the keymap. */
export const containerCommand = (id: string): string => `workbench.view.extension.${id}`;

const commitMenu = (section: string, entries: [string, string][], extraWhen = '') =>
  entries.map(([command, group]) => ({ command, group, when: `webviewId == 'unintellij.commit' && webviewSection == '${section}'${extraWhen}` }));
const CHANGELISTS_ON = ' && config.unintellij.vcs.changelists.enabled';

const logMenu = (entries: [string, string][]) => entries.map(([command, group]) => ({ command, group, when: "webviewId == 'unintellij.gitLog' && webviewSection == 'commit'" }));

const PROJECT_ITEM = "view == unintellij.project && viewItem =~ /^(file|folder)$/";

